import type { Metadata } from "next";import Link from "next/link";import { notFound } from "next/navigation";import { ArticleView } from "@/components/blog/article-view";import { requireAdmin } from "@/lib/admin/authorization";import { coverUrl,getPostById } from "@/lib/blog/service";import { getPreferences } from "@/lib/i18n/get-translations";
export const metadata:Metadata={robots:{index:false,follow:false},title:"Preview article"};
export default async function Preview({params}:{params:Promise<{id:string}>}){const actor=await requireAdmin("CONTENT_READ"),prefs=await getPreferences(actor.id),{id}=await params,post=await getPostById(id);if(!post)notFound();return <main className="min-h-screen bg-white"><div className="sticky top-0 z-10 border-b bg-white/95 px-4 py-3"><div className="mx-auto max-w-3xl"><Link className="font-bold text-teal-700 underline" href={`/admin/content/posts/${id}`}>← Quay lại chỉnh sửa</Link></div></div><ArticleView coverUrl={await coverUrl(post.coverMediaId)} locale={prefs.interfaceLanguage} post={post} preview/></main>}
